// ============================================================================
// FAO Error Handler - Extract Failure
// ----------------------------------------------------------------------------
// FAO-GOV-008: set as errorWorkflow on the flagship, the notifier (gateway)
// and the sweeper. Every failed execution of one of them reaches this node,
// and Record Run Failure passes it to fao_run_fail(execution id, failed
// node, message, source), which writes exactly one durable record: the
// FAILED ledger row on the run it attaches to, or one workflow_failures row.
//
// source is chosen here from fixed facts, never from the error text:
//   - the failed workflow's id, through SOURCE_BY_WORKFLOW (one entry per
//     line; check-exports holds it equal to the exports);
//   - a flagship failure whose last node is in PRE_CLAIM_NODES is
//     'flagship_pre_claim': every flagship node that is not Respond 202 and
//     not downstream of it (Claim Run, Claim OK?, Respond 400 and Respond
//     Claim Refused included; check-exports computes the set from the
//     flagship's connections and holds this list equal to it). Such an
//     execution holds no claimed run, so it must not attach to an older run
//     with the same execution id. A claim that committed and then errored
//     inside Claim Run or Claim OK? is left to the sweep's stale-run rule.
// A workflow id outside the map, or a payload without an execution id,
// fails this execution loudly and records nothing (n8n keeps the failed
// execution).
//
// The node name and the error message are untrusted text: control
// characters become spaces and they are cut to 200 and 500 characters.
// ============================================================================

const SOURCE_BY_WORKFLOW = {
  'uhB2KjEaJDuviM4D': 'flagship',
  'mUAC9qIMkVzlV5qw': 'gateway',
  'FaoSweeperV1x001': 'sweeper',
};

const PRE_CLAIM_NODES = [
  'Webhook: Invoke',
  'Validate Invoke Body',
  'Body Valid?',
  'Respond 400',
  'Claim Run',
  'Claim OK?',
  'Respond Claim Refused',
];

const ID_RE = /^[A-Za-z0-9]{1,64}$/;

const data = (($input.first() || {}).json) || {};
const execution = data.execution && typeof data.execution === 'object' ? data.execution : {};
const workflow = data.workflow && typeof data.workflow === 'object' ? data.workflow : {};

const wfId = typeof workflow.id === 'string' || typeof workflow.id === 'number' ? String(workflow.id) : '';
if (!ID_RE.test(wfId) || !Object.prototype.hasOwnProperty.call(SOURCE_BY_WORKFLOW, wfId)) {
  const shown = ID_RE.test(wfId) ? wfId : 'unknown';
  throw new Error(`FAO-GOV-008 error handler: workflow ${shown} is not in the error handler source map; nothing was recorded`);
}

const id = execution.id;
if (id === undefined || id === null || id === '') {
  throw new Error('FAO-GOV-008 error handler: the error payload has no execution id');
}

const clean = (v, max) => String(v === undefined || v === null ? '' : v)
  .replace(/[\u0000-\u001f\u007f]/g, ' ')
  .slice(0, max);

const err = execution.error && typeof execution.error === 'object' ? execution.error : {};
const lastNode = typeof execution.lastNodeExecuted === 'string' ? execution.lastNodeExecuted : '';

let source = SOURCE_BY_WORKFLOW[wfId];
if (source === 'flagship' && PRE_CLAIM_NODES.includes(lastNode)) source = 'flagship_pre_claim';

return [{
  json: {
    n8n_execution_id: String(id),
    failed_node: clean(execution.lastNodeExecuted, 200),
    message: clean(err.message, 500),
    source
  }
}];
